package ru.neverland.townyjustice;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.locks.ReentrantLock;import ru.neverland.core.*;import static ru.neverland.townyjustice.JusticePayment.Step.*;
public final class JusticeTreasurySmoke {
    static int checks;interface Work{void run()throws Exception;}static void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}static void denied(Work work,String m)throws Exception{try{work.run();}catch(Exception e){check(true,m);return;}throw new AssertionError(m);}static <T>T done(CompletionStage<T> s)throws Exception{return s.toCompletableFuture().get(5,TimeUnit.SECONDS);}
    public static void main(String[] args)throws Exception{
        var file=Files.createTempDirectory("justice-treasury").resolve("data.yml");var repo=new JusticeRepository(file);repo.load();var c=new JusticeCase(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),JusticeCase.Kind.WARRANT,500,1,"Native caller migration",1,999999,JusticeCase.Phase.FUNDING,null,null,null,null,0,0);var old=new JusticePayment(UUID.randomUUID(),c.id(),c.town(),c.subject(),JusticePayment.Kind.BOUNTY_FUND,c.amount(),READY,1,0);c=c.payment(old.id(),JusticeCase.Phase.FUNDING);repo.put(c,old);
        var y=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(file.toFile());y.set("payments."+old.id()+".route",null);Files.writeString(file,y.saveToString());var migrated=new JusticeRepository(file);migrated.load();check(migrated.get(old.id()).route()==JusticePayment.Route.LEGACY,"Historical route is legacy");check(old.treasury().treasuryId().equals(old.id()),"Stable existing payment UUID");denied(()->old.step(DEBIT_PENDING,2).treasury(),"Unknown legacy debit cannot become a new request");
        var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)field.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),k->new ReentrantLock());lock.lock();var before=repo.state();var next=new JusticeRepository.State(before.cases(),Map.of(old.id(),old.treasury()),before.prisons());CompletionStage<JusticeRepository.State> pending;
        try{pending=repo.commitAsync(before,next);check(!pending.toCompletableFuture().isDone()&&repo.busy()&&repo.get(old.id()).route()==JusticePayment.Route.LEGACY,"No publication before physical ACK");denied(()->repo.put(old),"Legacy writer cannot race asynchronous snapshot");check(CompletableFuture.supplyAsync(()->SuiteState.tryRun("justice-test",()->{})).get(2,TimeUnit.SECONDS),"Slow disk does not hold Suite monitor");}finally{lock.unlock();}
        done(pending);check(repo.get(old.id()).route()==JusticePayment.Route.TREASURY,"Route published after ACK");var reloaded=new JusticeRepository(file);reloaded.load();check(reloaded.state().equals(repo.state()),"Route survives restart exactly");
        var store=new JusticePaymentsSmoke.Store(old.treasury());var bank=new JusticePaymentsSmoke.Bank();denied(()->JusticePayments.advance(old.id(),3,0,store,bank),"Legacy engine refuses Treasury route");check(bank.debits==0&&store.writes==0,"No legacy hidden call or mutation");denied(()->JusticePayments.resolve(old.treasury().step(DEBIT_PENDING,3),"debit-applied",4),"Treasury receipt cannot be settled in legacy resolver");
        var held=old.treasury().step(COMPLETE,4);var wanted=c.phase(JusticeCase.Phase.WANTED);var refund=new JusticePayment(UUID.randomUUID(),c.id(),c.town(),c.subject(),JusticePayment.Kind.BOUNTY_REFUND,c.amount(),CREDIT_PENDING,5,5,JusticePayment.Route.TREASURY);var refunding=wanted.settlement(refund.id(),JusticeCase.Phase.REFUNDING);done(repo.commitAsync(repo.state(),new JusticeRepository.State(Map.of(c.id(),refunding),Map.of(held.id(),held,refund.id(),refund),Map.of())));check(repo.get(refund.id()).treasuryId().equals(refund.id()),"Refund identity independent and stable");var recovered=new JusticeRepository(file);recovered.load();check(recovered.get(refund.id()).step()==CREDIT_PENDING&&recovered.get(refund.id()).route()==JusticePayment.Route.TREASURY,"Restart retains unresolved refund without replay");
        var retry=refund.rejectedRefund(10);check(retry.step()==DEBITED&&retry.treasuryAttempt()==1&&!retry.treasuryId().equals(refund.treasuryId()),"Known rejected refund gets separate durable attempt identity");check(retry.step(CREDIT_PENDING,11).treasuryId().equals(retry.treasuryId()),"Same refund attempt keeps UUID across state changes");denied(()->retry.rejectedRefund(12),"Only actual pending refund can accept a rejection receipt");var current=repo.state();var payments=new HashMap<>(current.payments());payments.put(retry.id(),retry);done(repo.commitAsync(current,new JusticeRepository.State(current.cases(),payments,current.prisons())));var attemptCopy=new JusticeRepository(file);attemptCopy.load();check(attemptCopy.get(retry.id()).treasuryId().equals(retry.treasuryId())&&attemptCopy.get(retry.id()).treasuryAttempt()==1,"Restart retains next refund attempt before its bank call");done(attemptCopy.prepareClose());
        for(var r:List.of(repo,migrated,reloaded,recovered))done(r.prepareClose());System.out.println("JusticeTreasurySmoke PASS "+checks+" checks");
    }
}
